//! Unrun read-only Naukri summary fixtures; retained evidence never becomes new acceptance.
async fn owner_naukri_status(c:&mut PgConnection,values:BTreeMap<String,String>)->Result<Value>{let config=Configuration::from_values(&values).unwrap();automated_apply_agents::execution::dispatch_body_configured(c,automated_apply_agents::execution::route("/api/v1/execution/naukri").unwrap(),"GET",None,&[],Some(&config)).await}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_naukri_summary_is_read_only_under_owner_lock_and_does_not_expire_private_alerts(){
    let(mut c,_context,packet)=browser_command_fixture().await;let policy=owner_preparation_policy(&mut c).await;owner_execution_call(&mut c,"/api/v1/execution/naukri/automation/policy","PUT",json!({"expected_revision":0,"policy":policy})).await.unwrap();let stale=Uuid::new_v4();let retained=json!({"id":stale,"state":"NEEDS_INPUT","expires_at":"2000-01-01T00:00:00Z","private_reference":"retained"});browser_save(&mut c,&format!("nau_alert:{stale}"),retained.clone()).await;let current=Uuid::new_v4();browser_save(&mut c,&format!("nau_alert:{current}"),json!({"id":current,"state":"NEEDS_INPUT","expires_at":"2099-01-01T00:00:00Z"})).await;let mut automation=browser_pref(&mut c,"naukri_automation").await;automation["source_lease"]=json!("PRIVATE_SOURCE_LEASE_CANARY");browser_save(&mut c,"naukri_automation",automation).await;let before=browser_snapshot(&mut c).await;let mut owner=connection().await;let mut held=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *held).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();let status=owner_naukri_status(&mut c,browser_values()).await.unwrap();assert_eq!(status["automation"]["alert_candidates"].as_array().unwrap().len(),1);assert_eq!(status["automation"]["policy_context"]["profile_version"],packet["candidate_profile_version"]);assert_eq!(status["automation"]["counts"]["alert_candidates"],1);assert_eq!(status["submitted"],false);assert_eq!(status["capabilities"]["live_verified"],false);assert_eq!(status["automation"]["chrome_profile"]["status"],"CONNECTED");assert!(!status.to_string().contains("PRIVATE_SOURCE_LEASE_CANARY"));assert!(!status.to_string().contains("profile_secret"));assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(browser_pref(&mut c,&format!("nau_alert:{stale}")).await,retained);held.rollback().await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_naukri_summary_streams_large_retained_receipts_and_counts_damaged_evidence_without_enabling_submission(){
    let(mut c,_)=packet_service_fixture().await;sqlx::query("INSERT INTO owner_preferences(key,value) SELECT 'naukri_receipt:'||(123456789000+i)::text,jsonb_build_object('damaged',true) FROM generate_series(0,10100) i").execute(&mut c).await.unwrap();let at:Value=sqlx::query_scalar("SELECT to_jsonb(clock_timestamp())").fetch_one(&mut c).await.unwrap();let receipt=json!({"requisition":"123456799999","confirmation_source":"naukri_application_status_ui","operation_mode":"owner_authorized_software_operated_ui","status":"Application Sent","persistent_after_reload":true,"private_evidence_sha256":"a".repeat(64),"observed_at":at});browser_save(&mut c,"naukri_receipt:123456799999",receipt).await;let status=owner_naukri_status(&mut c,host_values()).await.unwrap();assert_eq!(status["automation"]["application_receipts"]["naukri_recorded"],1);assert_eq!(status["automation"]["application_receipts"]["records_requiring_review"],10101);assert_eq!(status["automation"]["counts"]["installed_worker_recorded"],0);assert_eq!(status["automation"]["application_receipts"]["live_reverified_by_this_read"],false);assert_eq!(status["capabilities"]["recurring_submission"]["enabled"],false);assert_eq!(status["account_session"]["identity_verified"],false);assert!(status.to_string().len()<20000);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_naukri_summary_reports_scoped_alert_generations_and_retains_no_tokens_in_projection(){
    let(mut c,_)=packet_service_fixture().await;let mut values=host_values();values.insert("GMAIL_LOCAL_ALLOWED_EMAILS".into(),json!(["owner-one@example.org","owner-two@example.org"]).to_string());browser_save(&mut c,"gm54_account:1",json!({"status":"connected","generation":2,"private_auth":"PRIVATE_ACCOUNT_CANARY"})).await;browser_save(&mut c,"gm54_account:2",json!({"status":"connected","generation":9})).await;browser_save(&mut c,"gm54_alerts:1",json!({"version":3,"enabled":true,"generation":2,"last_check_at":"2026-11-16T00:00:00Z","lease":"PRIVATE_LEASE_CANARY","page_token":"PRIVATE_PAGE_CANARY"})).await;browser_save(&mut c,"gm54_alerts:2",json!({"version":3,"enabled":true,"generation":8,"last_check_at":"2026-11-16T00:00:00Z"})).await;let before=browser_snapshot(&mut c).await;let status=owner_naukri_status(&mut c,values).await.unwrap();assert_eq!(status["automation"]["gmail_alert_discovery"][0]["enabled"],true);assert_eq!(status["automation"]["gmail_alert_discovery"][1]["enabled"],false);assert_eq!(status["automation"]["gmail_alert_discovery"][1]["configured_enabled"],true);assert_eq!(status["automation"]["job_candidate_discovery"],true);assert_eq!(status["automation"]["email_source_activation_available"],false);assert!(!status.to_string().contains("PRIVATE_"));assert_eq!(browser_snapshot(&mut c).await,before);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_naukri_summary_http_keeps_get_put_and_owner_auth_boundaries(){
    let(mut c,_)=packet_service_fixture().await;let(url,stop,server)=http_fixture_values(browser_values()).await;let http=client();let path=format!("{url}/api/v1/execution/naukri");assert_eq!(http.get(&path).send().await.unwrap().status(),401);assert_eq!(http.get(&path).bearer_auth(HOST_TOKEN).header("x-agent-client",BROWSER_EXTENSION).send().await.unwrap().status(),403);let before=browser_snapshot(&mut c).await;let status=http.get(&path).bearer_auth(HOST_TOKEN).send().await.unwrap();assert_eq!(status.status(),200);assert_eq!(status.json::<Value>().await.unwrap()["configuration"]["mode"],"ON_DEMAND");assert_eq!(browser_snapshot(&mut c).await,before);let invalid=http.post(&path).bearer_auth(HOST_TOKEN).send().await.unwrap();assert_eq!(invalid.status(),405);assert_eq!(invalid.headers().get("allow").unwrap(),"GET, PUT");assert_eq!(http.put(&path).bearer_auth(HOST_TOKEN).json(&json!({"mode":"OFF"})).send().await.unwrap().status(),200);assert_eq!(http.get(&path).bearer_auth(HOST_TOKEN).send().await.unwrap().json::<Value>().await.unwrap()["configuration"]["mode"],"OFF");stop.cancel();server.await.unwrap();
}
